/**
 * Energy Markets — Static Data Engine
 *
 * Reads pre-fetched market data from data/market-data.json
 * (generated by scripts/fetch_market_data.py via GitHub Actions).
 * No CORS proxy needed — the JSON is served from the same origin.
 */

// ─── Market Data Store ──────────────────────────────────────────────────────

let marketData = null; // Loaded from JSON
const liveSpots = {};  // commodity name → price

